 write(OUT/'Notebook_Execution.json',{'status':'passed','code_cells':counter,'all_cells_executed':True,'error_outputs':0,'seed':SEED,'python':sys.version.split()[0],'classifiers_fit':0,'predictions_generated':False,'new_notebook_sha256':sha(path),'diagnostics':len(env['study'].figures),'elapsed_seconds':time.perf_counter()-start,'notebook_bytes':path.stat().st_size})
